examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
MonarchEmojiPicker(
        onEmojiPicked = { picked = it },
        recentlyUsed = listOf("👍", "🎉", "✅"),
        modifier = Modifier.height(376.dp),
    )
    MonarchText(text = "Last picked: " + (picked ?: "none yet"))
}

MonarchReactionBar(
    reactions = reactions.map { (emoji, count) -> MonarchReactionBarItem(emoji, count = count) },
    onToggle = { emoji, on -> reactions = reactions + (emoji to (reactions[emoji] ?: 0) + if (on) 1 else -1) },
    picker = { onPick, onDismiss ->
        MonarchBottomSheet(onDismissRequest = onDismiss) { MonarchEmojiPicker(onEmojiPicked = onPick) }
    },
)
